// ============================================================
// API Configuration — Gemini Only (Free Forever)
// Only 1 key needed in .env:
//   REACT_APP_GEMINI_API_KEY → aistudio.google.com/app/apikey
//
// OPTIMIZED: Only 2 Gemini calls per full diagnostic run
//   Call 1 → Get all 3 model responses in one prompt
//   Call 2 → Analyze all responses + generate report
// ============================================================

const GEMINI_MODEL = "gemini-2.0-flash-lite";

async function geminiRequest(prompt, maxTokens = 2000) {
  const apiKey = process.env.REACT_APP_GEMINI_API_KEY;
  if (!apiKey) throw new Error("Missing REACT_APP_GEMINI_API_KEY in .env — get it free at aistudio.google.com/app/apikey");

  const res = await fetch(
    `https://generativelanguage.googleapis.com/v1beta/models/${GEMINI_MODEL}:generateContent?key=${apiKey}`,
    {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        contents: [{ parts: [{ text: prompt }] }],
        generationConfig: { maxOutputTokens: maxTokens },
      }),
    }
  );

  if (res.status === 429) {
    throw new Error("Rate limit hit. Please wait 60 seconds and try again.");
  }

  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    throw new Error(`Gemini API error: ${err?.error?.message || res.status}`);
  }

  const data = await res.json();
  return data.candidates?.[0]?.content?.parts?.[0]?.text || "";
}

// ── CALL 1: Get all 3 model responses in one single API call ──
export async function callAllModels(query) {
  const prompt = `You are simulating 3 different AI assistants answering the same question.
For each assistant, respond in their distinct style. Give each response separately.

Question: "${query}. Give me 4-6 specific product recommendations with brief reasons."

