  const raw = await geminiRequest(prompt, 2000);

  // Parse the 3 responses from the single output
  const chatgpt = extractSection(raw, "CHATGPT", "CLAUDE");
  const claude  = extractSection(raw, "CLAUDE",  "GEMINI");
  const gemini  = extractSection(raw, "GEMINI",  null);

  return { chatgpt, claude, gemini };
}

function extractSection(text, startTag, endTag) {
  const start = text.indexOf(`===${startTag}===`);
  if (start === -1) return "";
  const contentStart = start + `===${startTag}===`.length;
  const end = endTag ? text.indexOf(`===${endTag}===`) : text.length;
  return text.slice(contentStart, end === -1 ? text.length : end).trim();
}

